// decoAssets.ts
// Everything the decoration page draws comes from here:
//
//   STICKERS   cut-out pictures (src/assets/stickers/<category>/*.webp). The list is
//              GENERATED by tools/stickers/make_stickers.py into stickerManifest.ts.
//   TEXT       plain letters in one of four fonts and one of five colours. Nothing else:
//              no outline, no shadow, no gloss. Drawn on a canvas at high resolution.
//
// Both end up as an image (data URL / file URL) + an aspect ratio, so the on-screen
// preview and the saved PNG draw exactly the same pixels.

import { STICKER_CATEGORIES, STICKER_FILES } from "./stickerManifest";

export { STICKER_CATEGORIES };

export interface Art {
  src: string;     // image URL / data URL
  aspect: number;  // height / width
  pixel?: boolean; // pixel art: scale with hard edges, never smoothed
  natW?: number;   // original width in px (used to give new stickers a sensible size)
}

// ---------------------------------------------------------------------
// stickers
// ---------------------------------------------------------------------

export const STICKERS = STICKER_FILES;
const byId = new Map(STICKER_FILES.map((s) => [s.id, s]));
const stickerCache = new Map<string, Art>();

export function stickerArt(id: string): Art {
  let art = stickerCache.get(id);
  if (!art) {
    const f = byId.get(id) ?? STICKER_FILES[0];
    art = { src: f.src, aspect: f.h / f.w, pixel: f.pixel, natW: f.w };
    stickerCache.set(id, art);
  }
  return art;
}

export const stickersIn = (category: string) =>
  STICKER_FILES.filter((s) => s.category === category);

// ---------------------------------------------------------------------
// fonts + colours (the fonts live in src/assets/fonts/, each with its licence file)
// ---------------------------------------------------------------------

import tiktokUrl from "../assets/fonts/TikTokSans-Bold.ttf";
import gondensUrl from "../assets/fonts/Gondens-DEMO.otf";
import ammoniteUrl from "../assets/fonts/Ammonite.otf";
import experimentalUrl from "../assets/fonts/ExperimentalBM-Regular.ttf";

export type FontId = "tiktok" | "gondens" | "ammonite" | "experimental";

export interface FontChoice {
  id: FontId;
  label: string;
  family: string;          // the name it is registered under (prefixed so it never clashes with an installed font)
  url: string;
  weight: string;
  lowercaseOnly?: boolean; // the font has no capital letters: text is lowercased so nothing falls back
  note?: string;           // shown under the font chips when this font is picked
  chip: { label: string; size: number }; // the chip in the picker: short name + size that fits (px)
}

// To add a font: put the file in src/assets/fonts/, import it above and add a line here.
// Characters a font does not have are drawn in TikTok Sans (same colour), never in a random serif.
export const FONTS: FontChoice[] = [
  { id: "tiktok", label: "TikTok Sans", family: "Deco TikTok Sans", url: tiktokUrl, weight: "700", chip: { label: "TikTok Sans", size: 17 } },
  {
    id: "gondens",
    label: "Gondens",
    family: "Deco Gondens",
    url: gondensUrl,
    weight: "400",
    chip: { label: "Gondens", size: 21 },
    note: "DEMO font: letters only. Numbers and symbols use TikTok Sans.",
  },
  {
    id: "ammonite",
    label: "Ammonite",
    family: "Deco Ammonite",
    url: ammoniteUrl,
    weight: "400",
    lowercaseOnly: true,
    chip: { label: "ammonite", size: 19 },
    note: "Lowercase letters only. Numbers and symbols use TikTok Sans.",
  },
  {
    id: "experimental",
    label: "Experimental",
    family: "Deco Experimental",
    url: experimentalUrl,
    weight: "400",
    chip: { label: "Exp. BM", size: 14 },
    note: "Has letters and numbers, but no ? @ # & or -. Those use TikTok Sans.",
  },
];

export const DEFAULT_FONT: FontId = "tiktok";

export const TEXT_COLOURS = [
  { id: "aqua", hex: "#00FFEF", label: "Aqua" },
  { id: "pink", hex: "#FF1694", label: "Pink" },
  { id: "ink", hex: "#272727", label: "Ink" },
  { id: "cloud", hex: "#F5F5F5", label: "Cloud" },
  { id: "lime", hex: "#C3CF3F", label: "Lime" },
];

export const DEFAULT_COLOUR = TEXT_COLOURS[1].hex;

const fontById = new Map(FONTS.map((f) => [f.id, f]));

let fontVersion = 0;
let fontsPromise: Promise<boolean> | null = null;

/** loads all the fonts once. Resolves true if at least one loaded. */
export function ensureFonts(): Promise<boolean> {
  if (!fontsPromise) {
    fontsPromise = (async () => {
      const results = await Promise.all(
        FONTS.map(async (f) => {
          try {
            const face = new FontFace(f.family, `url(${f.url})`, { weight: f.weight });
            await face.load();
            document.fonts.add(face);
            return true;
          } catch {
            return false; // a broken file must never break the page
          }
        })
      );
      fontVersion++;
      textCache.clear(); // text drawn before the fonts were ready is redrawn
      return results.some(Boolean);
    })();
  }
  return fontsPromise;
}

/** CSS font-family value for UI that shows a font in its own face */
export const fontCss = (f: FontChoice) => `"${f.family}", "Deco TikTok Sans", sans-serif`;

// ---------------------------------------------------------------------
// text: plain letters, one solid colour
// ---------------------------------------------------------------------

export const TEXT_PRESETS = [
  "bestie",
  "y2k",
  "xoxo",
  "cutie",
  "2003",
  "photobooth",
  "angel",
  "only u",
];

const textCache = new Map<string, Art>();

function makeCanvas(w: number, h: number) {
  const c = document.createElement("canvas");
  c.width = w;
  c.height = h;
  return c;
}

export function textArt(rawText: string, fontId: FontId, colour: string): Art {
  const font = fontById.get(fontId) ?? FONTS[0];
  let text = rawText.trim() === "" ? " " : rawText;
  if (font.lowercaseOnly) text = text.toLowerCase();

  const key = `${fontVersion}|${font.id}|${colour}|${text}`;
  const hit = textCache.get(key);
  if (hit) return hit;

  const fs = 200; // drawn big, so it stays sharp when scaled up in the saved PNG
  const css = `${font.weight} ${fs}px "${font.family}", "Deco TikTok Sans", Arial, sans-serif`;

  const probe = makeCanvas(8, 8).getContext("2d")!;
  probe.font = css;
  const m = probe.measureText(text);

  // the same line height for every word in a font ("xoxo" must not come out taller than "bestie"):
  // reference letters with an ascender and a descender
  const ref = probe.measureText("bdhkgypq");
  const asc = Math.max(m.actualBoundingBoxAscent, ref.actualBoundingBoxAscent);
  const desc = Math.max(m.actualBoundingBoxDescent, ref.actualBoundingBoxDescent);
  const left = m.actualBoundingBoxLeft;
  const textW = Math.max(m.width, left + m.actualBoundingBoxRight);

  const pad = Math.round(fs * 0.1); // just enough that nothing is clipped
  const w = Math.ceil(textW) + pad * 2;
  const h = Math.ceil(asc + desc) + pad * 2;

  const canvas = makeCanvas(w, h);
  const ctx = canvas.getContext("2d")!;
  ctx.font = css;
  ctx.textBaseline = "alphabetic";
  ctx.textAlign = "left";
  ctx.fillStyle = colour;
  ctx.fillText(text, pad + left, pad + asc); // plain fill: no stroke, no shadow, no gloss

  const art: Art = { src: canvas.toDataURL("image/png"), aspect: h / w };
  textCache.set(key, art);
  return art;
}

// ---------------------------------------------------------------------
// image loading
// ---------------------------------------------------------------------

const imageCache = new Map<string, Promise<HTMLImageElement>>();

export function loadImage(src: string): Promise<HTMLImageElement> {
  let p = imageCache.get(src);
  if (!p) {
    p = new Promise((resolve, reject) => {
      const img = new Image();
      img.onload = () => resolve(img);
      img.onerror = () => reject(new Error("Could not load image"));
      img.src = src;
    });
    // don't cache huge photos forever: only art (small data URLs / file URLs)
    if (src.length < 200000) imageCache.set(src, p);
  }
  return p;
}
